INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (367212, 15102, 'South China Morning Post', 'en', 'The ugly side of pressure on White House women to maintain Trump’s ‘Maga perfect’ image', 'https://www.scmp.com/news/world/united-states-canada/article/3364371/ugly-side-pressure-white-house-women-maintain-trumps-maga-perfect-image', 'Women working in US President Donald Trump’s White House were not surprised that press secretary Karoline Leavitt announced last week she was leaving her job – and they do not think it was just because she wants to spend time with her young children. In an interview with the Daily Mail, several anonymous White House employees spoke of the pressure that Leavitt, executive assistant Natalie Harper and other female staff are under to adhere daily to a “Maga perfect” standard of beauty that requires...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/18/2750d5b4-40fd-419a-a5a0-fe1cdc6621f6_97064c0e.jpg?itok=NxBWzwkO&v=1787025378', '2026-08-18T03:56:20+00:00', '2026-08-18T04:05:07.838766'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
