INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (356327, 15151, 'Mint', 'en', 'Jharkhand protest: Round 7 of talks with Govt on day 16 of hunger strike today', 'https://www.livemint.com/news/india/jharkhand-protest-round-7-of-talks-with-govt-today-on-day-16-of-hunger-strike-today-whats-the-latest-hemant-soren-11786940448693.html', 'Student leader Devendra Nath Mahto, who is on 16th day of hunger strike over alleged irregularities in the Jharkhand Public Service Commission (JPSC) and Jharkhand Staff Selection Commission (JSSC), has called for permanent reforms in the education system.', 'https://www.livemint.com/lm-img/img/2026/08/17/1600x900/logo/PTI08-16-2026-000229B-0_1786942096556_1786942112516_f6476ff0-c51d-4faf-965e-6ea9e3ed69e1.jpg', '2026-08-17T05:03:38+00:00', '2026-08-17T05:36:40.432066'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (356360, 15151, 'Dainik Jagran', 'hi', 'लखनऊ में फिर Gen Alpha का प्रदर्शन: बदहाल सुविधाओं को लेकर सड़क पर उतरीं छात्राएं, बालागंज चौराहा जाम - gen alpha protest jaiprakash narayan sarvodaya school girls students protest poor facilities lucknow', 'https://news.google.?oc=5', 'लखनऊ में फिर Gen Alpha का प्रदर्शन: बदहाल सुविधाओं को लेकर सड़क पर उतरीं छात्राएं, बालागंज चौराहा जाम - gen alpha protest jaiprakash narayan sarvodaya school girls students protest poor facilities lucknow Jagran', '', '2026-08-17T04:51:00+00:00', '2026-08-17T05:37:09.805959'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (356418, 15151, 'Aaj Tak', 'hi', 'स्कूल में टीचर नहीं, हमारी पढ़ाई से खिलवाड़, फूटा Gen-अल्फा का गुस्सा', 'https://www.aajtak.in/education/news/story/hundreds-of-school-students-take-to-streets-block-balaganj-chowk-over-teacher-shortage-lucknow-ngix-rpti-2623677-2026-08-17', 'जंतर-मंतर और झारखंड में हुए प्रदर्शन को लेकर विवाद अभी तक थमा नहीं था कि अब लखनऊ में Gen Alfa का विवाद सामने आ गया है. शिक्षकों की कमी से नाराज सैकड़ों स्कूली छात्रों ने सड़क पर उतरकर विरोध प्रदर्शन किया. दुबग्गा के जयप्रकाश नारायण स्कूल के छात्रों ने बालागंज चौराहे पर धरना दिया, जिससे दुबग्गा रोड पर यातायात पूरी तरह प्रभावित हो गया. वह अपने आने वाले भविष्य और पढ़ाई के साथ हो रहे खिलवाड़ से दुखी हैं.', '', '2026-08-17T05:13:46+00:00', '2026-08-17T05:37:19.867469'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
